function maxProfit(prices) {
  const memo = new Map();                        // day * 2 + holding -> best profit
  const best = (day, holding) => {
    if (day >= prices.length) return 0;
    const key = day * 2 + (holding ? 1 : 0);
    if (memo.has(key)) return memo.get(key);
    let result = best(day + 1, holding);         // do nothing today
    if (holding) result = Math.max(result, prices[day] + best(day + 2, false));   // sell; tomorrow is cooldown
    else result = Math.max(result, -prices[day] + best(day + 1, true));          // buy
    memo.set(key, result);
    return result;
  };
  return best(0, false);
}

