int best(int[] prices, int day, int holding) {   // the most profit from day on
    if (day >= prices.length) return 0;
    if (memo[day][holding] != null) return memo[day][holding];
    int result = best(prices, day + 1, holding); // do nothing today
    if (holding == 1) result = Math.max(result, prices[day] + best(prices, day + 2, 0));   // sell; tomorrow is cooldown
    else result = Math.max(result, -prices[day] + best(prices, day + 1, 1));             // buy
    memo[day][holding] = result;
    return result;
}

vector<vector<int>> memo;                        // -1 = not solved yet (profits are never negative)

int best(vector<int>& prices, int day, int holding) {   // the most profit from day on
    if (day >= (int)prices.size()) return 0;
    int& m = memo[day][holding];
    if (m != -1) return m;
    int result = best(prices, day + 1, holding); // do nothing today
    if (holding) result = max(result, prices[day] + best(prices, day + 2, 0));   // sell; tomorrow is cooldown
    else result = max(result, -prices[day] + best(prices, day + 1, 1));         // buy
    return m = result;
}

int maxProfit(vector<int>& prices) {
    memo.assign(prices.size(), vector<int>(2, -1));
    return best(prices, 0, 0);
}

function maxProfit(prices) {
  let hold = -prices[0], sold = 0, rest = 0;     // best profit ending the day holding / having just sold / resting
  for (const p of prices) {
    const prevSold = sold;
    sold = hold + p;                             // sell the share we held
    hold = Math.max(hold, rest - p);             // keep it, or buy: only from rest, never right after a sale
    rest = Math.max(rest, prevSold);             // yesterday's sale makes today a cooldown
  }
  return Math.max(sold, rest);
}

def max_profit(prices):
    hold, sold, rest = -prices[0], 0, 0   # best profit ending the day holding / having just sold / resting
    for p in prices:
        # every right-hand side uses yesterday's values
        hold, sold, rest = max(hold, rest - p), hold + p, max(rest, sold)
    return max(sold, rest)

